from decimal import Decimal, InvalidOperation

def is_decimal(value: str) -> bool:
    try:
        d = Decimal(value)
    except (InvalidOperation, ValueError):
        return False
    # Normalize to remove trailing zeros and decimal point if unnecessary
    d = d.normalize()
    # If the number is an integer, exponent will be >= 0
    if d.as_tuple().exponent >= 0:
        return True
    # exponent is negative, check if at most 2 decimal places
    return abs(d.as_tuple().exponent) <= 2

